// Normalizzazione dati provenienti dal Form
const input = $input.first();
const binaryData = input.binary || {};
const videoFile = {};

// Separa il video e l'immagine di copertina in base al tipo MIME o ad altri criteri
for (const key in binaryData) {
  const file = binaryData[key];
  if (file.mimeType && file.mimeType.startsWith('video/')) {
    videoFile['video'] = file;
  } else if (file.mimeType && file.mimeType.startsWith('image/')) {
    videoFile['cover_image'] = file;
  }
}

// Fallback nel caso in cui non sia stato possibile determinare il tipo MIME
if (!videoFile['video']) {
  for (const key in binaryData) {
    if (!videoFile['cover_image'] || binaryData[key] !== videoFile['cover_image']) {
      videoFile['video'] = binaryData[key];
      break;
    }
  }
}

return [{ 
  json: {
    source: 'form',
    link_veicolo: input.json['Link Veicolo'],
    modello_macchina: input.json['Modello Macchina'],
    titolo_youtube: input.json['Titolo Video YouTube'],
    account_social: input.json['Account Social Ufficiale'],
    piattaforme: input.json['Piattaforme di Pubblicazione'],
    sede_riferimento: input.json['Sede di Riferimento'],
    data_programmazione: input.json['Data Pubblicazione (Opzionale)'],
    ora_programmazione: input.json['Ora Pubblicazione (Opzionale)'],
    copy_personalizzato: input.json['Copy Personalizzato (Opzionale)']
  },
  binary: videoFile
}];

const input = $input.first();
const html = input.json.data || '';
const originalData = $("Normalize Form Data").first().json;

let cleanText = '';
try {
  cleanText = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
} catch (e) {
  cleanText = 'Non è stato possibile caricare la pagina del veicolo.';
}

cleanText = cleanText.substring(0, 12000);

return [{
  json: {
    link_veicolo: originalData.link_veicolo,
    modello_macchina: originalData.modello_macchina,
    titolo_youtube: originalData.titolo_youtube,
    account_social: originalData.account_social,
    piattaforme: originalData.piattaforme,
    sede_riferimento: originalData.sede_riferimento,
    data_programmazione: originalData.data_programmazione,
    ora_programmazione: originalData.ora_programmazione,
    specifiche_veicolo: cleanText
  },
  binary: $("Normalize Form Data").first().binary
}];

const input = $input.first();
const binaryData = input.binary || {};
const resultBinary = {
  video: binaryData.video
};
if (binaryData.cover_image) {
  resultBinary.cover_image = binaryData.cover_image;
}

const modello = input.json.modello_macchina;
const link = input.json.link_veicolo;
const account = input.json.account_social;
const platformsInput = input.json.piattaforme;
const titolo_youtube = input.json.titolo_youtube;
const sede = input.json.sede_riferimento;
let dateInput = (input.json.data_programmazione || "").trim();
const timeInput = (input.json.ora_programmazione || "10:00").trim();
let scheduled_date = "";

if (dateInput) {
  // Convert standard Italian format (DD/MM/YYYY or DD-MM-YYYY) to YYYY-MM-DD
  if (dateInput.includes("/") || dateInput.includes("-")) {
    const separator = dateInput.includes("/") ? "/" : "-";
    const parts = dateInput.split(separator);
    if (parts.length === 3) {
      if (parts[0].length === 4) {
        // YYYY-MM-DD
        dateInput = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
      } else {
        // DD-MM-YYYY -> YYYY-MM-DD
        dateInput = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
      }
    }
  }
  const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
  const time = timeRegex.test(timeInput) ? timeInput : "10:00";
  scheduled_date = `${dateInput}T${time}:00`;
}

const platforms = Array.isArray(platformsInput) ? platformsInput : [platformsInput];

let baseCaption = (input.json.copy_personalizzato && input.json.copy_personalizzato.trim() !== ""
  ? input.json.copy_personalizzato
  : (input.json.text || input.json.output || "")
).replace(/\*/g, "").trim();

const sediTexts = {
  "Account_Social_1 - Roma (Auto Nuove e Usate)": "🚘 Concessionaria Auto 🛻 Auto Nuove e Usate Multimarca\n🐴 Allestimenti Speciali\n☎️ 0612345678 📧 roma@concessionaria.it\n📍 Via Flaminia 123, Roma\n💻 www.concessionaria.it",
  "Sede Secondaria - Milano": "🚗 Concessionaria Auto 🚙 Gamma Veicoli\n☎️ 0212345678 📧 milano@concessionaria.it\n📍 Via Montenapoleone 45, Milano\n💻 www.concessionaria.it",
  "Sede Terziaria - Torino": "🛻 Concessionaria Auto 🚘 Gamma City Car e SUV\n☎️ 01112345678 📧 torino@concessionaria.it\n📍 Corso Vittorio Emanuele 16, Torino\n💻 www.concessionaria.it",
  "Sede Quaternaria - Bologna": "🛻 Concessionaria Auto 🚙 Auto Km0 e Usato Garantito\n🚘 Gamma City Car\n🚘 Gamma Crossover e SUV\n☎️ 05112345678 📧 bologna@concessionaria.it\n📍 Via dell Indipendenza 84, Bologna\n💻 www.concessionaria.it",
  "Sede Test": "📷 Studio Digitale - Servizio Foto & Video\n📍 Via Garibaldi 12, Genova"
};

const sedeText = sediTexts[sede] || "";

let gbp_location_id = "";
if (sede) {
  if (sede.includes("Roma")) {
    gbp_location_id = "locations/1111111111111111111";
  } else if (sede.includes("Milano")) {
    const modelloLower = modello.toLowerCase();
    if (modelloLower.includes("lancia")) {
      gbp_location_id = "locations/2222222222222222221";
    } else if (modelloLower.includes("abarth")) {
      gbp_location_id = "locations/2222222222222222222";
    } else {
      gbp_location_id = "locations/2222222222222222223";
    }
  } else if (sede.includes("Torino")) {
    const modelloLower = modello.toLowerCase();
    if (modelloLower.includes("aixam") || modelloLower.includes("minicar")) {
      gbp_location_id = "locations/3333333333333333331";
    } else {
      gbp_location_id = "locations/3333333333333333332";
    }
  } else if (sede.includes("Bologna")) {
    gbp_location_id = "locations/4444444444444444444";
  } else if (sede.includes("Test")) {
    gbp_location_id = "locations/5555555555555555555";
  }
}

const platformMap = {
  "Facebook": "facebook",
  "Instagram": "instagram",
  "TikTok": "tiktok",
  "Google Business": "google_business",
  "YouTube": "youtube"
};

const outputItems = [];

for (const platform of platforms) {
  const apiPlatform = platformMap[platform] || platform.toLowerCase();

  const hasLink = ["Facebook", "YouTube", "Google Business"].includes(platform) && link && link.trim() !== "" && link.startsWith("http");
  const caption = hasLink 
    ? `${baseCaption}\n\nScopri di più sul nostro sito:\n🔗 ${link}\n\n${sedeText}`.trim()
    : `${baseCaption}\n\n${sedeText}`.trim();

  let finalCaption = caption;
  if (apiPlatform === "google_business" && finalCaption.length > 1499) {
    finalCaption = finalCaption.substring(0, 1496) + "...";
  }

  outputItems.push({
    json: {
      modello,
      link,
      account,
      piattaforma: apiPlatform,
      titolo_youtube,
      gbp_location_id,
      caption: finalCaption,
      scheduled_date,
      timezone: "Europe/Rome"
    },
    binary: resultBinary
  });
}

return outputItems;
